from taf.cloud.cbam.schemas.schema_base import CbamSchema


class OperationExecutionLinks(CbamSchema):
    def __init__(self, self_link=None, cancel=None, operation_params=None, end_notification=None, additional_data=None,
                 list_link=None, vnf=None):
        self.self_link = self_link
        self.cancel = cancel
        self.operation_params = operation_params
        self.end_notification = end_notification
        self.additional_data = additional_data
        self.list_link = list_link
        self.vnf = vnf

    @classmethod
    def from_response_dict(cls, response_dict):
        def get_href_attribute(response, key):
            return response[key]['href'] if key in response else None

        self_link = response_dict['self']['href']
        cancel = get_href_attribute(response_dict, 'cancel')
        operation_params = get_href_attribute(response_dict, 'operationParams')
        end_notification = get_href_attribute(response_dict, 'endNotification')
        additional_data = get_href_attribute(response_dict, 'additionalData')
        list_link = get_href_attribute(response_dict, 'list')
        vnf = get_href_attribute(response_dict, 'vnf')
        return cls(self_link=self_link, cancel=cancel, operation_params=operation_params,
                   end_notification=end_notification, additional_data=additional_data, list_link=list_link, vnf=vnf)

    def as_dict(self):
        attributes = {'cancel': self.cancel, 'operationParams': self.operation_params,
                      'endNotification': self.end_notification, 'additionalData': self.additional_data,
                      'list': self.list_link, 'vnf': self.vnf}

        result = {k: {'href': v} for k, v in attributes.items() if v}
        result['self'] = {'href': self.self_link}

        return result


class OperationExecution(CbamSchema):
    def __init__(self, operation_id=None, vnf_instance_id=None, operation_type=None, status=None,
                 is_cancel_pending=None, start_time=None, operation_name=None, cancel_mode=None, error=None,
                 finish_time=None, grant_id=None, operation_params=None, additional_data=None, metadata=None,
                 links=None):
        self.operation_id = operation_id
        self.vnf_instance_id = vnf_instance_id
        self.operation_type = operation_type
        self.status = status
        self.is_cancel_pending = is_cancel_pending
        self.start_time = start_time
        self.operation_name = operation_name
        self.cancel_mode = cancel_mode
        self.error = error
        self.finish_time = finish_time
        self.grant_id = grant_id
        self.operation_params = operation_params
        self.additional_data = additional_data
        self.metadata = metadata
        self.links = links

    @classmethod
    def from_response_dict(cls, response_dict):
        links = None
        if '_links' in response_dict:
            links = OperationExecutionLinks.from_response_dict(response_dict['_links'])
        return cls(operation_id=response_dict['id'],
                   vnf_instance_id=response_dict['vnfInstanceId'],
                   operation_type=response_dict['operationType'],
                   status=response_dict['status'],
                   is_cancel_pending=response_dict.get('isCancelPending', None),
                   start_time=response_dict['startTime'],
                   operation_name=response_dict.get('operationName', None),
                   cancel_mode=response_dict.get('cancelMode', None),
                   error=response_dict.get('error', None),
                   finish_time=response_dict.get('finishTime', None),
                   grant_id=response_dict.get('grantId', None),
                   operation_params=response_dict.get('operationParams', None),
                   additional_data=response_dict.get('additionalData', None),
                   metadata=response_dict.get('metadata', None),
                   links=links)

    def as_dict(self):
        result = {'id': self.operation_id,
                  'vnfInstanceId': self.vnf_instance_id,
                  'operationType': self.operation_type,
                  'status': self.status,
                  'startTime': self.start_time}

        links = None
        if self.links is not None:
            links = self.links.as_dict()

        attributes = {'operationName': self.operation_name, 'cancelMode': self.cancel_mode,
                      'error': self.error, 'finishTime': self.finish_time,
                      'grantId': self.grant_id, 'operationParams': self.operation_params,
                      'additionalData': self.additional_data, 'metadata': self.metadata,
                      '_links': links,
                      'isCancelPending': self.is_cancel_pending}

        attributes = {k: v for k, v in attributes.items() if v}
        result.update(attributes)

        return result
